            { type: "fill", question: "2.31 The ability to work with numbers is called ___.", answer: ["numeracy", "Numeracy"], hint: "Hisob savodxonligi.", explanation: "<b>\u2705 To\x27g\x27ri javob: numeracy</b><br><b>\ud83d\udcd6 Tushuntirish:</b> Hisob savodxonligi.<br><b>\ud83d\udca1 Eslab qoling:</b> Bu so\x27zni gap ichida to\x27g\x27ri ishlatishga e\x27tibor bering." },
            { type: "fill", question: "2.32 Students doing their first degree are called ___.", answer: ["undergraduates", "Undergraduates"], hint: "Bakalavr talabalari.", explanation: "<b>\u2705 To\x27g\x27ri javob: undergraduates</b><br><b>\ud83d\udcd6 Tushuntirish:</b> Bakalavr talabalari.<br><b>\ud83d\udca1 Eslab qoling:</b> Bu so\x27zni gap ichida to\x27g\x27ri ishlatishga e\x27tibor bering." },
            { type: "fill", question: "2.33 Money students borrow and repay after graduating are student ___.", answer: ["loans"], hint: "Talaba kreditlari.", explanation: "<b>\u2705 To\x27g\x27ri javob: loans</b><br><b>\ud83d\udcd6 Tushuntirish:</b> Talaba kreditlari.<br><b>\ud83d\udca1 Eslab qoling:</b> Bu so\x27zni gap ichida to\x27g\x27ri ishlatishga e\x27tibor bering." },
            { type: "match", question: "2.34 Match the education terms with their meanings:", pairs: [{"left": "selective", "right": "pupils chosen by exam results"}, {"left": "comprehensive", "right": "all students attend same school"}, {"left": "elitism", "right": "favouring privileged groups"}, {"left": "tertiary", "right": "university or college level"}, {"left": "curriculum", "right": "subjects taught in a school"}], hint: "Ta'lim atamalari.", explanation: "<b>\u2705 To\x27g\x27ri juftliklar:</b><br>1. selective \u2192 pupils chosen by exam results<br>2. comprehensive \u2192 all students attend same school<br>3. elitism \u2192 favouring privileged groups<br>4. tertiary \u2192 university or college level<br>5. curriculum \u2192 subjects taught in a school<br><b>\ud83d\udcd6 Tushuntirish:</b> Ta'lim atamalari." },
            { type: "rewrite", question: "2.35 Rewrite using a more formal word: 'Schools that accept students based on exam results' → ___ schools", answer: ["Selective schools", "selective schools"], hint: "Tanlov asosidagi.", explanation: "<b>\u2705 Namuna javob: Selective schools</b><br><b>\ud83d\udcd6 Tushuntirish:</b> Tanlov asosidagi.<br><b>\ud83d\udca1 Maslahat:</b> Gapni qayta yozishda asosiy ma\x27no saqlanishi kerak." },
            { type: "rewrite", question: "2.36 Rewrite formally: 'Giving money to help students pay for university' → providing ___ or bursaries", answer: ["scholarships", "Scholarships"], hint: "Stipendiyalar.", explanation: "<b>\u2705 Namuna javob: scholarships</b><br><b>\ud83d\udcd6 Tushuntirish:</b> Stipendiyalar.<br><b>\ud83d\udca1 Maslahat:</b> Gapni qayta yozishda asosiy ma\x27no saqlanishi kerak." }
